create or replace function private.get_organization_team_impl(p_organization_id uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$
begin
 if (select auth.uid()) is null or not private.can_manage_organization(p_organization_id) then raise exception 'Only organization owners and administrators can view team access.'; end if;
 return jsonb_build_object('members',coalesce((select jsonb_agg(jsonb_build_object('id',u.id,'user_id',u.id,'email',lower(u.email),'full_name',coalesce(nullif(trim(p.full_name),''),nullif(trim(u.raw_user_meta_data->>'full_name'),''),nullif(trim(u.raw_user_meta_data->>'name'),''),nullif(trim(concat_ws(' ',u.raw_user_meta_data->>'first_name',u.raw_user_meta_data->>'last_name')),'')),'roles',coalesce(a.roles,'{}'::text[]),'viewer_permissions',coalesce(a.viewer_permissions,'{}'::text[]),'league_ids',coalesce(a.league_ids,'{}'::uuid[]),'owner',exists(select 1 from public.organization_memberships m where m.organization_id=p_organization_id and m.user_id=u.id and m.role='owner'),'status','active') order by lower(u.email)) from auth.users u left join public.profiles p on p.id=u.id join(select distinct user_id from public.organization_memberships where organization_id=p_organization_id union select user_id from public.organization_user_access_profiles where organization_id=p_organization_id) people on people.user_id=u.id left join public.organization_user_access_profiles a on a.organization_id=p_organization_id and a.user_id=u.id),'[]'::jsonb),'invitations',coalesce((select jsonb_agg(jsonb_build_object('id',i.id,'email',lower(i.email),'full_name',coalesce(nullif(trim(p.full_name),''),nullif(trim(u.raw_user_meta_data->>'full_name'),''),nullif(trim(u.raw_user_meta_data->>'name'),''),nullif(trim(concat_ws(' ',u.raw_user_meta_data->>'first_name',u.raw_user_meta_data->>'last_name')),'')),'roles',case when cardinality(i.roles)>0 then i.roles else array[i.role] end,'viewer_permissions',i.viewer_permissions,'league_ids',i.league_ids,'status','pending') order by i.created_at desc) from public.organization_invitations i left join auth.users u on lower(u.email)=lower(i.email) left join public.profiles p on p.id=u.id where i.organization_id=p_organization_id and i.status='pending'),'[]'::jsonb));
end $$;

notify pgrst,'reload schema';
